  // ✅ УСИЛЕННАЯ ПРОВЕРКА AST
  if (!ast) {
    console.warn(`⚠️ Не удалось получить AST для файла: ${filePath}`);
    return null;
  }

  // ✅ ПРОВЕРКА НА НАЛИЧИЕ body
