            }
          : undefined,
      },
      null,
      2
    ),
    'utf-8'
  );

  console.log(`\n${'='.repeat(60)}`);
  console.log('✅ ПРОМПТ ДЛЯ РАЗБИЕНИЯ СОЗДАН!');
