  const files: string[] = [];
  for (const p of paths) {
    if (fs.existsSync(p)) {
      const stat = fs.statSync(p);
      if (
        stat.isFile() &&
        (p.endsWith('.ts') || p.endsWith('.tsx') || p.endsWith('.js') || p.endsWith('.jsx'))
      ) {
        files.push(path.resolve(p));
      } else if (stat.isDirectory()) {
        const pattern = `${p}/**/*.{ts,tsx,js,jsx}`;
        const matched = await glob(pattern, {
          ignore: ['**/node_modules/**', '**/dist/**', '**/build/**'],
        });
        files.push(...matched.map(f => path.resolve(f)));
      }
    }
  }

  if (files.length === 0) {
    console.error('❌ No files found to analyze');
    return {
      success: false,
      metrics: {
        totalFunctions: 0,
        totalFiles: 0,
        unusedFunctions: 0,
        unusedVariables: 0,
        potentialBugs: 0,
        verifiedFunctions: 0,
        cyclomaticComplexity: 0,
        dataFlowIssues: 0,
        typeErrors: 0,
        cyclicDependencies: 0,
        unreachableBlocks: 0,
      },
      issues: [],
      verificationResults: [],
      timestamp: new Date().toISOString(),
      duration: 0,
    };
  }

  return pipeline.run(files, options);
}

