    // ============================================
    if (['ForStatement', 'WhileStatement', 'DoWhileStatement'].includes(n.type)) {
      if (n.body) traverse(n.body);
    }

    // ============================================
    // 11. FOR-IN / FOR-OF
    // ============================================
    if (n.type === 'ForInStatement' || n.type === 'ForOfStatement') {
      if (n.body) traverse(n.body);
    }

