// src/reporters/modules/types.ts
// Общие типы для всех модулей

export interface GraphData {
  rootKey: string;
  graph: Record<string, string[]>;
  hasCycles?: boolean;
  cyclicEdges?: string[];
}

export interface EntitiesResult {
  functions: any[];
  classes: any[];
  constants: any[];
  interfaces: any[];
  types: any[];
  variables: any[];
  imports: any[];
  exports: any[];
  callGraph: Record<string, string[]>;
  moduleName: string;
  filePath: string;
}

// ============================================================
// БАЗОВЫЙ ТИП ДЛЯ ФУНКЦИИ - ИСПОЛЬЗУЕТСЯ ВЕЗДЕ
// ============================================================

export interface FunctionEntity {
  name: string;
  params: string[];
  paramTypes?: string[];
  line: number;
  startLine?: number;
  endLine?: number;
  isAsync: boolean;
  isExported: boolean;
  isMethod?: boolean;
  className?: string;
  calls: string[];
  calledBy: { function: string; module: string; line: number }[] | string[];
  returnType?: string;
  body?: string; // ✅ ПОЛНОЕ ТЕЛО ФУНКЦИИ
  signature?: string; // ✅ СИГНАТУРА ДЛЯ БЫСТРОГО ПРОСМОТРА
  vscode?: string; // ✅ ССЫЛКА НА VS CODE
  isNested?: boolean;
  parentFunction?: string;
  isArrow?: boolean;
  isEventHandler?: boolean;
  eventType?: string;
  depth?: number;
  complexity?: number;
  security?: {
    hasEval: boolean;
    hasProcessEnv: boolean;
    hasSensitiveData: boolean;
    hasExec: boolean;
    hasPassword: boolean;
  };
  _safeInfo?: any;
}

// ============================================================
// ENHANCED TYPES - РАСШИРЯЮТ БАЗОВЫЕ
// ============================================================

export interface EnhancedFunctionInfo extends FunctionEntity {
  // Расширяет FunctionEntity, добавляя только то, чего нет
  // Все поля уже есть в FunctionEntity
}

export interface EnhancedConstantInfo {
  name: string;
  value?: any;
  line: number;
  isExported: boolean;
  type?: string;
  _safeInfo?: any;
}

export interface EnhancedVariableInfo {
  name: string;
  value?: any;
  line: number;
  isExported: boolean;
  type?: string;
  _safeInfo?: any;
}

export interface EnhancedInterfaceInfo {
  name: string;
  properties: string[];
  line: number;
  isExported: boolean;
  extends?: string[];
  startLine?: number;
  endLine?: number;
  _safeInfo?: any;
}

export interface EnhancedTypeInfo {
  name: string;
  definition: string;
  line: number;
  isExported: boolean;
  _safeInfo?: any;
}

export interface EnhancedClassInfo {
  name: string;
  methods: string[];
  methodDetails?: {
    name: string;
    params: string[];
    returnType?: string;
    isAsync: boolean;
    line: number;
  }[];
  properties: string[];
  propertyDetails?: {
    name: string;
    type?: string;
    line: number;
  }[];
  line: number;
  isExported: boolean;
  extends?: string;
  implements?: string[];
  startLine?: number;
  endLine?: number;
  body?: string; // ✅ ТЕЛО КЛАССА
  vscode?: string; // ✅ ССЫЛКА НА VS CODE
  _safeInfo?: any;
}

export interface EnhancedEntityInfo {
  functions: EnhancedFunctionInfo[];
  constants: EnhancedConstantInfo[];
  variables: EnhancedVariableInfo[];
  interfaces: EnhancedInterfaceInfo[];
  types: EnhancedTypeInfo[];
  classes: EnhancedClassInfo[];
}

export interface ModuleNode {
  id: string;
  name: string;
  type: 'module' | 'component' | 'vue';
  level: number;
  metadata: {
    size: number;
    lines: number;
    language: string;
    isEntry: boolean;
  };
}

export interface ModuleEdge {
  from: string;
  to: string;
  type: 'import' | 'external' | 're-export';
  specifiers: string[];
}

export interface ModuleGraph {
  nodes: ModuleNode[];
  edges: ModuleEdge[];
}

export interface EntityNode {
  id: string;
  name: string;
  type: 'function' | 'class' | 'constant' | 'interface' | 'type' | 'variable';
  module: string;
  line: number;
  metadata: Record<string, any>;
}

export interface EntityEdge {
  from: string;
  to: string;
  type:
    | 'function_call'
    | 'constant_reference'
    | 'class_extends'
    | 'class_implements'
    | 'interface_extends'
    | 'type_reference'
    | 'method_call'
    | 'property_access'
    | 'import_binding'
    | 'export_binding'
