        }
        if (!exists) {
          uniqueExports.push({ ...exp, exports: [...exp.exports] });
        }
      }
      exportsFlow[modulePath].exportsTo = uniqueExports;
    }
  }

  return {
    imports: importsFlow,
    exports: exportsFlow,
  };
